#!/usr/bin/env python3
"""Compare all 49 crops and 12 assembled expressions against v16. --clean before publishing."""
from pathlib import Path
import subprocess,sys
CONTOURS_HTML='<!doctype html><html lang="pt-BR"><meta charset="utf-8"><title>Revisão de contornos — todas as poses</title><style>body{font:16px system-ui;background:#f3efdf;color:#253d32;margin:20px}#cards{display:grid;grid-template-columns:repeat(2,520px);gap:14px}article{background:white;padding:10px}canvas{width:250px;height:300px;background:#173047}h2{font-size:17px;margin:5px}span{display:inline-block;width:250px}button,select{padding:10px;margin:5px}article div{display:flex;gap:4px}</style><h1>Contornos: versão 16 × correção</h1><p>Todos os recortes vêm dos mesmos originais. Fundo contrastante expõe o papel residual.</p><button id="render">Revisar todas as poses</button><button id="compact">Ver as 49 correções</button><button id="dark">Fundo azul escuro</button><button id="pink">Fundo rosa</button><p id="status">Preparando…</p><div id="cards"></div><script src="__sprite-v16.js"></script><script>const oldPrepare=prepareReferencePixels;</script><script src="sprite-rendering.js"></script><script>\ndocument.getElementById(\'compact\').onclick=()=>{document.getElementById(\'cards\').style.gridTemplateColumns=\'repeat(7,165px)\';document.querySelectorAll(\'article\').forEach(c=>{c.style.padding=\'4px\';c.querySelector(\'div\').firstChild.style.display=\'none\';c.querySelectorAll(\'span\').forEach(s=>s.style.display=\'none\');c.querySelectorAll(\'canvas\').forEach(cv=>{cv.style.width=\'155px\';cv.style.height=\'186px\'})})};const imgs={};let oldMeta,meta;async function init(){[oldMeta,meta]=await Promise.all([fetch(\'__poses-v16.json\').then(r=>r.json()),fetch(\'assets/canon/poses.json\').then(r=>r.json())]);await Promise.all(Object.entries(meta.provenance).map(([name,p])=>new Promise(resolve=>{const i=new Image;i.onload=()=>{imgs[name]=i;resolve()};i.src=\'assets/canon/\'+p.file})));document.getElementById(\'status\').textContent=\'Originais prontos.\'}init();\ndocument.getElementById(\'dark\').onclick=()=>document.querySelectorAll(\'canvas\').forEach(c=>c.style.background=\'#173047\');document.getElementById(\'pink\').onclick=()=>document.querySelectorAll(\'canvas\').forEach(c=>c.style.background=\'#b64074\');\ndocument.getElementById(\'render\').onclick=()=>{const root=document.getElementById(\'cards\');root.replaceChildren();for(const name of Object.keys(meta.poses)){const card=document.createElement(\'article\');card.innerHTML=\'<h2>\'+name+\'</h2><span>Versão 16</span><span>Correção</span>\';const row=document.createElement(\'div\');card.append(row);root.append(card);for(const [m,prepare] of [[oldMeta,oldPrepare],[meta,prepareReferencePixels]]){const p=m.poses[name],raw=document.createElement(\'canvas\');raw.width=p.w+4;raw.height=p.h+4;const ctx=raw.getContext(\'2d\');ctx.drawImage(imgs[p.sheet],p.sx,p.sy,p.w,p.h,2,2,p.w,p.h);const frame=ctx.getImageData(0,0,raw.width,raw.height);frame.data.set(prepare(frame.data,raw.width,raw.height,p.runs,{paperRows:p.paperRows,neckFade:p.neck?p.h-p.neck.blendStart:0,sourceHeight:p.h}));ctx.putImageData(frame,0,0);const cv=document.createElement(\'canvas\');cv.width=500;cv.height=600;const g=cv.getContext(\'2d\');const scale=Math.min(440/raw.width,560/raw.height);g.drawImage(raw,(500-raw.width*scale)/2,580-raw.height*scale,raw.width*scale,raw.height*scale);row.append(cv)}}document.getElementById(\'status\').textContent=Object.keys(meta.poses).length+\' poses comparadas.\'};\n</script></html>\n'
ASSEMBLED_HTML='<!doctype html><html lang="pt-BR"><meta charset="utf-8"><title>Expressões completas — contornos e pescoço</title><style>body{font:16px system-ui;background:#f3efdf;margin:20px}iframe{position:absolute;left:-5000px;width:940px;height:900px}#grid{display:grid;grid-template-columns:repeat(6,190px);gap:10px}canvas{width:184px;height:250px;background:#173047}h2{font-size:15px;margin:5px}button{padding:10px}</style><h1>Expressões completas: preservar bochechas e pescoço</h1><button id="run">Revisar expressões completas</button><p id="status">Preparando…</p><div id="grid"></div><iframe id="game" src="index.html"></iframe><script>\nconst frame=document.getElementById(\'game\');const timer=setInterval(()=>{if(frame.contentWindow.PippoCanon?.ready){clearInterval(timer);frame.contentWindow.eval(\'state.paused=true\');document.getElementById(\'status\').textContent=\'Desenhos prontos.\'}},100);\ndocument.getElementById(\'run\').onclick=()=>{const w=frame.contentWindow;const grid=document.getElementById(\'grid\');grid.replaceChildren();for(const name of w.PippoCanon.names){w.eval(\'state.motion=null;state.turn=null;state.sideRest=false;state.actorX=.5;state.blink=0;state.pet=0;state.expression=\'+JSON.stringify(name)+\';render()\');const source=w.document.getElementById(\'pippo\'),g=w.eval(\'geometry()\'),ratio=source.width/g.width,cv=document.createElement(\'canvas\');cv.width=368;cv.height=500;cv.getContext(\'2d\').drawImage(source,(g.cx-g.bodyHeight*.56)*ratio,(g.bottom-g.bodyHeight*1.08)*ratio,g.bodyHeight*1.12*ratio,g.bodyHeight*1.12*ratio,0,66,368,368);const card=document.createElement(\'article\');card.innerHTML=\'<h2>\'+name+\'</h2>\';card.append(cv);grid.append(card)}document.getElementById(\'status\').textContent=\'12 expressões compostas e conferíveis.\'};\n</script></html>\n'
root=Path(__file__).resolve().parents[1]
files=['__sprite-v16.js','__poses-v16.json','__contours.html','__assembled.html']
if '--clean' in sys.argv:
 for name in files:(root/'dist'/name).unlink(missing_ok=True)
 raise SystemExit

def source(name):
 for revision,prefix in [('6f7cdf8cdf73571be168b33be1ebb25717222592',''),('51e0f50b57fa07a198eb23929d49692f79347325','prototypes/pippo-25d/')]:
  r=subprocess.run(['git','show',revision+':'+prefix+'dist/'+name],cwd=root,capture_output=True)
  if r.returncode==0:return r.stdout
 raise SystemExit('Version 16 source unavailable in checkout history.')
(root/'dist/__sprite-v16.js').write_bytes(source('sprite-rendering.js'))
(root/'dist/__poses-v16.json').write_bytes(source('assets/canon/poses.json'))
(root/'dist/__contours.html').write_text(CONTOURS_HTML)
(root/'dist/__assembled.html').write_text(ASSEMBLED_HTML)
print('Open /__contours.html and /__assembled.html through the supported Site preview; --clean before publication.')
